                    [ 'Гравіювання шкіри', 'Дуже точне, дрібні написи й логотипи', 'Швидке, зокрема на великих площах' ],
                    [ 'Різання', 'Тонка шкіра; товща — за кілька проходів', 'Товста шкіра швидше, за меншу кількість проходів' ],
                    [ 'Найкраще для', 'Персоналізації, дрібних виробів, роботи вдома', 'Серій, великих шматків, ременів і нашийників' ],
                    [ 'Обмеження', 'Повільніше ріже товсту шкіру, краї темніші', 'Більший і дорожчий; потрібна продуктивна витяжка' ],
                ] ],
